import { billing as billingApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { useAuth } from '@/features/auth/session.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { safeExternalUrl } from '@/lib/externalLinks.js';
import { useTheme } from '@/lib/theme.js';
import { openCheckout } from './paddle.js';
import { buyOnPlay, onAndroid } from './play.js';
import { AlmostThere, Celebrate } from './Celebrate.js';
import { FreeForYou } from './FreeForYou.js';
import {
  PLAY_SUBSCRIPTIONS_URL,
  canBuyHere,
  canManage,
  freeSide,
  managedInPlay,
  paidPrices,
  price,
  useBilling,
  yearlySaving,
} from './state.js';
import { getActiveNotebook } from '@/db/repo.js';
