/**
 * The paywall. It opens from Settings and shows what Pro costs; the purchase
 * itself happens in the seller's own sheet — Paddle's overlay on the web,
 * Google Play's inside the Android app. Which one is not a preference: a
 * purchase made in the app must go through Play, whose rules do not allow
 * anything else for digital goods.
 *
 * Nothing here decides that anyone has paid. On the web the plan is read
 * from the server again, because the server learns from Paddle's own
 * notification; on Android the token Play returns is sent to the server,
 * which asks Google what it is worth. Neither seller's word to this app is
 * taken as proof on its own.
 */
export function Upgrade({ onClose }: { onClose: () => void }): React.JSX.Element {
  const state = useBilling((s) => s.state);
  const apply = useBilling((s) => s.apply);
  // The account the purchase is attached to. Play carries it through to
  // Google, and the server refuses a purchase that names anybody else.
  const accountId = useAuth((s) => s.user?.id);
  // The overlay follows the app's ground. 'system' resolves to whatever the
  // document is actually showing, which is what the theme script decided.
  const theme = useTheme((s) => s.theme);
  const dark = theme === 'system' ? document.documentElement.dataset.theme !== 'light' : theme === 'dark';
  const waitForPro = useBilling((s) => s.waitForPro);
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  /**
   * Where the purchase has got to. 'waiting' is after the provider said it
   * charged but before the server has heard, which is normally a second or
   * two; 'done' is only once the server agrees, so the celebration is never
   * a promise the next screen has to take back.
   */
  const [stage, setStage] = useState<'choosing' | 'waiting' | 'done'>('choosing');

  const prices = paidPrices(state);
  const yearly = prices.find((p) => p.id === 'pro_yearly');
  const monthly = prices.find((p) => p.id === 'pro_monthly');
  // What the yearly plan actually saves, worked out from the two prices the
  // server sent. Never a number written here: a claim about money that the
  // prices do not support is the one thing a paywall must not print.
  const saving = yearlySaving(state);

  /**
   * Google Play's way: its own sheet, then the token to the server.
   *
   * Once Play says the purchase happened, nothing that goes wrong afterwards
   * is this person's problem and none of it loses them their money. Play
   * holds the purchase, the app still holds the token, and Settings sends
   * every token it finds each time it opens — so a server that cannot reach
   * Google right now is a wait, not a failure. Telling somebody their
   * payment went wrong when the shop has already taken it is the one thing
   * this screen must never do.
   */
  const buyOnAndroid = async (plan: 'pro_monthly' | 'pro_yearly'): Promise<void> => {
    if (accountId === undefined || accountId === '') {
      // Without the account the purchase could not be attributed to anyone,
      // and the server would refuse it. Better not to open the sheet.
      setError(t('error.generic'));
      return;
    }
    const outcome = await buyOnPlay(plan, accountId);
    if (outcome.kind === 'closed') return;

    setStage('waiting');
    try {
      apply(await billingApi.verifyGooglePurchase(outcome.purchaseToken));
      setStage('done');
      // Pro arriving is the day's one big moment (features/celebrate).
      void import('@/features/celebrate/state.js')
        .then((celebrate) => celebrate.noteBigMoment())
        .catch(() => undefined);
    } catch {
      // Stay on "payment received". Play has it; we will ask again.
    }
  };

  /** Paddle's way: its overlay, then ask the server again. */
  const buyOnWeb = async (plan: 'pro_monthly' | 'pro_yearly'): Promise<void> => {
    const checkout = await billingApi.checkout(plan);
    const outcome = await openCheckout(checkout, dark ? 'dark' : 'light');
    if (outcome !== 'completed') {
      // The overlay was closed without paying. Nothing happened, and saying
      // so would be telling someone off for changing their mind.
      return;
    }
    // Paddle says it charged the card; the plan only changes once the
    // server hears that from Paddle itself.
    setStage('waiting');
    setStage((await waitForPro()) ? 'done' : 'waiting');
  };

  const buy = (plan: 'pro_monthly' | 'pro_yearly'): void => {
    setBusy(plan);
    setError(null);
    const bought = onAndroid() ? buyOnAndroid(plan) : buyOnWeb(plan);
    bought
      .catch((cause: unknown) => {
        setStage('choosing');
        if (isApiError(cause, 'offline')) setError(t('error.offline'));
        else if (isApiError(cause, 'notFound')) setError(t('upgrade.closed'));
        else setError(t('error.generic'));
      })
      .finally(() => {
        setBusy(null);
      });
  };

  if (stage === 'done') {
    return (
      <Sheet title={t('upgrade.title')} onClose={onClose}>
        <Celebrate until={state?.until} onDone={onClose} />
      </Sheet>
    );
  }
  if (stage === 'waiting') {
    return (
      <Sheet title={t('upgrade.title')} onClose={onClose}>
        <AlmostThere />
      </Sheet>
    );
  }

  return (
    <Sheet title={t('upgrade.title')} onClose={onClose}>
      <div className={styles.body}>
        <p className={styles.lead}>{t('upgrade.lead')}</p>

        <Perks />

        {yearly !== undefined && (
          <PlanButton
            title={t('upgrade.yearly')}
            amount={price(yearly.amountMinor, yearly.currency)}
            note={t('upgrade.yearlyNote', {
              monthly: price(Math.round(yearly.amountMinor / 12), yearly.currency),
            })}
            featured
            badge={saving === undefined ? undefined : t('upgrade.bestValue', { percent: saving })}
            busy={busy === 'pro_yearly'}
            disabled={busy !== null}
            onClick={() => {
              buy('pro_yearly');
            }}
          />
        )}
        {monthly !== undefined && (
          <PlanButton
            title={t('upgrade.monthly')}
            amount={price(monthly.amountMinor, monthly.currency)}
            note={t('upgrade.monthlyNote')}
            busy={busy === 'pro_monthly'}
            disabled={busy !== null}
            onClick={() => {
              buy('pro_monthly');
            }}
          />
        )}

        {prices.length === 0 && <p className={styles.note}>{t('upgrade.closed')}</p>}
        {error !== null && (
          <p className={styles.error} role="alert">
            {error}
          </p>
        )}

        {/* What somebody hesitating actually wants to know, before the small
            print rather than buried in it. Each line is a fact about how
            this works, not a reassurance we cannot keep. */}
        <ul className={styles.assurances}>
          <li>{t('upgrade.keep')}</li>
          <li>{t('upgrade.cancel')}</li>
          <li>{t('upgrade.noCard')}</li>
        </ul>

        <p className={styles.note}>{t('upgrade.terms')}</p>
        <p className={styles.note}>{t('upgrade.persian')}</p>
      </div>
    </Sheet>
  );
}

/**
 * What Pro is, said plainly (marketer, 2026-10-08). The two Pro practice
 * modes are named only where the server has switched them on for this
 * account: a perk somebody cannot find is a promise the app does not keep.
 * Nothing here claims fuller cards — the model writes the same card on every
 * plan — and nothing names a number.
 */
function Perks(): React.JSX.Element {
  const srs = useLiveQuery(loadSrsView, null, []);
  const sayIt = srs !== null && shows(srs, 'sayIt');
  const sentence = srs !== null && shows(srs, 'sentence');
  return (
    <ul className={styles.perks}>
      <li>{t('upgrade.perkLex')}</li>
      <li>{t('upgrade.perkRead')}</li>
      <li>{t('upgrade.perkCards')}</li>
      {sayIt && sentence && <li>{t('upgrade.perkPractice')}</li>}
      {sayIt && !sentence && <li>{t('upgrade.perkSayIt')}</li>}
      {sentence && !sayIt && <li>{t('upgrade.perkSentence')}</li>}
      <li>{t('upgrade.perkVoice')}</li>
      <li>{t('upgrade.perkNotebooks')}</li>
    </ul>
  );
}

/** One plan, as a button: what it is called, what it costs, and why. */
function PlanButton({
  title,
  amount,
  note,
  badge,
  featured = false,
  busy,
  disabled,
  onClick,
}: {
  title: string;
  amount: string;
  note: string;
  badge?: string | undefined;
  /** Draws the eye to the plan worth choosing, badge or no badge. */
  featured?: boolean;
  busy: boolean;
  disabled: boolean;
  onClick: () => void;
}): React.JSX.Element {
  return (
    <button
      type="button"
      className={cx(styles.plan, featured && styles.featured)}
      disabled={disabled}
      onClick={onClick}
    >
      <span className={styles.planHead}>
        <span className={styles.planTitle}>{title}</span>
        {badge !== undefined && <span className={styles.badge}>{badge}</span>}
      </span>
      <span className={styles.planAmount}>{busy ? t('upgrade.opening') : amount}</span>
      <span className={styles.planNote}>{note}</span>
    </button>
  );
}

/**
 * The row in Settings. It shows the plan, and offers to upgrade only when
 * the server says this client may sell.
 */
export function PlanRow({
  rowClass,
  labelClass,
  valueClass,
}: {
  rowClass: string | undefined;
  labelClass: string | undefined;
  valueClass: string | undefined;
}): React.JSX.Element {
  const state = useBilling((s) => s.state);
  const [open, setOpen] = useState(false);
  const [opening, setOpening] = useState(false);
  const [failed, setFailed] = useState(false);
  const notebook = useLiveQuery(getActiveNotebook, undefined, []);

  // Narrowing on the state itself, so its other fields are known below.
  const pro = state !== null && state.plan === 'pro' ? state : null;
  // A trial is Pro, with a date; buying during it starts the paid plan that
  // day, so the offer stays open beside it (Settings → Plan is one of the
  // places Pro may be offered).
  const [now] = useState(() => new Date());
  const trial = runningTrial(state, now);
  const prices = paidPrices(state);
  // A notebook Lexpad never charges for gets the opposite of a paywall. It
  // is checked before the offer, so somebody who is already free can never
  // be shown a price for what they already have — the one mistake this row
  // must not make.
  const free = pro === null ? freeSide(state, notebook?.targetLang, notebook?.meaningLang) : undefined;
  // During the trial the plan is Pro, so `free` above is not worked out; a
  // notebook Lexpad never charges for still hears nothing about a price.
  const freeHere = free ?? freeSide(state, notebook?.targetLang, notebook?.meaningLang);
  const offer =
    (pro === null || trial !== undefined) && freeHere === undefined && canBuyHere(state) && prices.length > 0;
  // The cheapest paid plan, so the row can carry a price rather than make
  // somebody open a sheet to find one.
  const cheapest = prices.reduce<(typeof prices)[number] | undefined>(
    (best, p) => (best === undefined || p.amountMinor < best.amountMinor ? p : best),
    undefined,
  );

  /**
   * Sends someone to the provider's own page to cancel or change a card.
   * The link is short-lived, so it is fetched at the moment of the tap
   * rather than held on the screen.
   */
  const manage = (): void => {
    setOpening(true);
    setFailed(false);
    billingApi
      .portal()
      .then((portal) => {
        // Only the provider's own portal; anything else is treated as a
        // link that could not be opened.
        const target = safeExternalUrl(portal.cancelUrl ?? portal.url, 'billingPortal');
        if (target === undefined) {
          setFailed(true);
          return;
        }
        // A new tab, because leaving the app to cancel and having no way
        // back would be a poor way to treat someone who is leaving.
        window.open(target.href, '_blank', 'noopener,noreferrer');
      })
      .catch(() => {
        setFailed(true);
      })
      .finally(() => {
        setOpening(false);
      });
  };

  return (
    <>
      {free !== undefined && (
        <button
          type="button"
          className={cx(rowClass, styles.button, styles.freeRow)}
          onClick={() => {
            setOpen(true);
          }}
        >
          <span className={labelClass}>{t('free.row')}</span>
          <span className={valueClass}>{t('free.rowNote')}</span>
        </button>
      )}
      {(trial !== undefined || (!offer && free === undefined)) && (
        <div className={rowClass}>
          <span className={labelClass}>{t('upgrade.plan')}</span>
          <span className={valueClass}>
            {trial === undefined ? planWords(pro) : t('trial.plan', { date: trialDate(trial.endsAt, now) })}
          </span>
        </div>
      )}
      {offer && cheapest !== undefined && (
        <button
          type="button"
          className={cx(rowClass, styles.button, styles.offerRow)}
          onClick={() => {
            setOpen(true);
          }}
        >
          <span className={labelClass}>{t('upgrade.row')}</span>
          <span className={valueClass}>
            {t('upgrade.rowNote', { amount: price(cheapest.amountMinor, cheapest.currency) })}
          </span>
        </button>
      )}
      {managedInPlay(state) && (
        <button
          type="button"
          className={cx(rowClass, styles.button)}
          onClick={() => {
            // Play is the seller here, so its own screen is the only place
            // that can cancel or change a card. There is no link of ours to
            // fetch and nothing that can be down.
            window.open(PLAY_SUBSCRIPTIONS_URL, '_blank', 'noopener,noreferrer');
          }}
        >
          <span className={labelClass}>{t('upgrade.manage')}</span>
          <span className={valueClass}>{t('upgrade.manageInPlay')}</span>
        </button>
      )}
      {canManage(state) && (
        <button type="button" className={cx(rowClass, styles.button)} disabled={opening} onClick={manage}>
          <span className={labelClass}>{t('upgrade.manage')}</span>
          <span className={valueClass}>
            {opening
              ? t('upgrade.manageOpening')
              : failed
                ? t('upgrade.manageFailed')
                : t('upgrade.manageNote')}
          </span>
        </button>
      )}
      {open &&
        (free === undefined ? (
          <Upgrade
            onClose={() => {
              setOpen(false);
            }}
          />
        ) : (
          <FreeForYou
            side={free.side}
            code={free.code}
            onClose={() => {
              setOpen(false);
            }}
          />
        ))}
    </>
  );
}

/** What the plan row says: free, paid, or paid and already ending. */
function planWords(pro: { until?: string; canceled?: boolean } | null): string {
  if (pro === null) return t('upgrade.planFree');
  const date = until(pro.until);
  /*
   * No date, no sentence about a date. A plan with no renewal on it -- a
   * promotion, a plan the provider has not told us the end of yet --
   * printed "Pro, until " with the date missing and the comma still there,
   * which reads as a bug and is one.
   */
  if (date === '') return t('upgrade.planProOpen');
  return pro.canceled === true
    ? t('upgrade.planEnding', { until: date })
    : t('upgrade.planPro', { until: date });
}

/** When a paid plan lapses, as a date. */
function until(iso: string | undefined): string {
  if (iso === undefined) return '';
  const when = new Date(iso);
  if (Number.isNaN(when.getTime())) return '';
  return when.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' });
}
