import { Burst } from '@/components/ui/Burst.js';
import styles from './Celebrate.module.css';
import { t } from '@/i18n/index.js';
import { longDate } from '@/lib/format.js';

/**
 * What someone sees the moment their payment lands: a tick that draws itself
 * and a little confetti.
 *
 * It appears only once the server confirms the plan, never when the browser
 * merely thinks the payment worked, so it is not a promise the next screen
 * has to take back.
 *
 * Everything moves through `styles/motion.css`, which stops all of it under
 * prefers-reduced-motion; what is left is the tick, three still sparkles,
 * the words and the button, which is the whole message anyway.
 */
export function Celebrate({
  until,
  onDone,
}: {
  until?: string | undefined;
  onDone: () => void;
}): React.JSX.Element {
  return (
    <div className={styles.celebrate} role="status">
      {/* The shared confetti (components/ui/Burst): it never takes a tap, and
          under reduced motion three still sparkles stand in for it. */}
      <Burst size="small" />

      <svg className={styles.tick} viewBox="0 0 52 52" aria-hidden="true">
        <circle className={styles.tickRing} cx="26" cy="26" r="24" />
        <path className={styles.tickMark} d="M15 27l8 8 15-16" />
      </svg>

      <h3 className={styles.title}>{t('upgrade.doneTitle')}</h3>
      <p className={styles.lead}>{t('upgrade.doneLead')}</p>
      {until !== undefined && (
        <p className={styles.note}>{t('upgrade.doneUntil', { until: longDate(until) })}</p>
      )}

      <button type="button" className={styles.done} onClick={onDone}>
        {t('upgrade.doneAction')}
      </button>
    </div>
  );
}

/** The renewal date, as a date. */
/**
 * What someone sees when the payment went through but the plan has not
 * caught up yet. It is not a failure: the provider tells the server in its
 * own time, and this is almost always seconds.
 */
export function AlmostThere(): React.JSX.Element {
  return (
    <div className={styles.celebrate} role="status">
      <span className={styles.spinner} aria-hidden="true" />
      <h3 className={styles.title}>{t('upgrade.pendingTitle')}</h3>
      <p className={styles.lead}>{t('upgrade.pendingLead')}</p>
    </div>
  );
}
